const listDefinitions={filmmakers:[['all','All entries'],['checked','Affiliation sources checked'],['unconfirmed','Specific affiliation unresolved'],['collectives','Named collectives'],['unlinked','No land link yet'],['credit-pending','No film credit yet'],['duplicates','Same-name records']],films:[['all','All credits'],['linked','Screening / watch pages'],['directing','Source-checked directing credits'],['undated','Undated credits'],['review','Credits needing review']],land:[['all','All land references'],['autonyms','Collected names A–Z'],['linked','With filmmakers'],['unlinked','No filmmakers indexed'],['unmapped','No mapped area'],['checked','With sourced connections']]};
