 $$('[data-film-facet]').forEach(b=>b.onclick=()=>{const kind=b.dataset.filmFacet,value=b.dataset.facetValue;s.film=null;s.returnContext=null;s.filmPage=0;s.filmLetter='';if(kind==='decade'){s.filters.from=value;s.filters.to=String(Number(value)+9);s.filters.undated=false;}else s.filters[kind]=value;syncFilterFields();applyFilters();});
