function filmFacetItems(kind){const previous=s.filters;s.filters={...previous};if(kind==='decade'){s.filters.from=s.filters.to='';s.filters.undated=true;}else s.filters[kind]='';try{return filmItems();}finally{s.filters=previous;}}
