function adjacentRecords(id){const origin=edgesByRecord.get(id)||[],matches=new Map();for(const sourceEdge of origin){for(const edge of visibleLandLinks(sourceEdge.land)){if(edge.record===id)continue;let item=matches.get(edge.record);if(!item){item={record:recordById(edge.record),links:[]};matches.set(edge.record,item);}item.links.push({land:edge.land,status:sourceEdge.status==='sourced'&&edge.status==='sourced'?'sourced':'provisional'});}}return [...matches.values()].sort((a,b)=>b.links.length-a.links.length||a.record.name.localeCompare(b.record.name));}
function adjacentDetail(id){const items=adjacentRecords(id);return items.length?`<details class="adjacent-makers"><summary>Shared land references · ${items.length} filmmakers</summary><p class="meta">Shared index references are a browsing route. They do not establish collaboration or residence.</p>${items.slice(0,5).map(({record:r,links})=>`<button class="adjacent-maker" data-adjacent-maker="${r.id}"><strong>${esc(r.name)}</strong><small>${links.slice(0,2).map(e=>esc(lands.find(l=>l.id===e.land).name)).join(' · ')} · ${links.every(e=>e.status==='sourced')?'sourced links':'includes provisional links'}</small></button>`).join('')}${items.length>5?'<p class="meta">Open a land reference above to explore all its linked filmmakers.</p>':''}</details>`:'';}
