function filmImage(f,compact=false){const m=mediaForFilm(f),url=imageURL(m?.image||f.thumbnailURL||f.imageURL);if(!url)return '';return `<figure class="film-artwork${compact?' compact':''}"><div class="artwork-frame"><img src="${esc(url)}" alt="Publicity image for ${esc(f.title)}" loading="${compact?'lazy':'eager'}" decoding="async" referrerpolicy="no-referrer"><span class="artwork-fallback" hidden>Film image unavailable</span></div><figcaption>${safe(m?.sourceURL)?`<a href="${esc(safe(m.sourceURL))}" target="_blank" rel="noopener noreferrer">Film image · ${esc(m.publisher)} ↗</a>`:'Film publicity image'}</figcaption></figure>`;}
function runtimeLabel(value){const seconds=Math.round(Number(value)*60);if(!Number.isFinite(seconds)||seconds<=0)return '';const mins=Math.floor(seconds/60),rest=seconds%60;return `${mins} min${rest?' '+rest+' sec':''}`;}
